namespace AutoMateApi;

public static class QuoteWorkflowSupport
{
    private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);
    public static async Task EnsureAsync(NpgsqlConnection connection,CancellationToken ct=default)
    {
        const string sql="""
CREATE TABLE IF NOT EXISTS public.tenant_quote_settings(tenant_id uuid PRIMARY KEY,default_validity_days integer NOT NULL DEFAULT 30,introduction_text text NOT NULL DEFAULT 'Thank you for the opportunity to quote for your property inspection.',updated_at timestamptz NOT NULL DEFAULT NOW(),CONSTRAINT ck_quote_validity CHECK(default_validity_days BETWEEN 1 AND 365));
CREATE TABLE IF NOT EXISTS public.quotes(quote_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_number text NOT NULL,status text NOT NULL,version integer NOT NULL,catalogue_version integer NOT NULL,canonical_address text NOT NULL,place_id text NOT NULL DEFAULT '',latitude double precision NULL,longitude double precision NULL,client_name text NOT NULL DEFAULT '',client_email text NOT NULL DEFAULT '',property_json jsonb NOT NULL DEFAULT '{}'::jsonb,imagery_json jsonb NOT NULL DEFAULT '{}'::jsonb,suggestions_json jsonb NOT NULL DEFAULT '[]'::jsonb,lines_json jsonb NOT NULL DEFAULT '[]'::jsonb,subtotal numeric(12,2) NOT NULL,gst numeric(12,2) NOT NULL,total numeric(12,2) NOT NULL,valid_until date NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT NOW(),updated_at timestamptz NOT NULL DEFAULT NOW(),accepted_at timestamptz NULL,declined_at timestamptz NULL,converted_at timestamptz NULL,UNIQUE(tenant_id,quote_number),CONSTRAINT ck_quote_status CHECK(status IN ('Draft','Ready','Sent','Viewed','Accepted','Declined','Expired','Converted')));
CREATE INDEX IF NOT EXISTS idx_quotes_tenant_updated ON public.quotes(tenant_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS public.quote_versions(quote_id uuid NOT NULL,tenant_id uuid NOT NULL,version integer NOT NULL,snapshot_json jsonb NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT NOW(),PRIMARY KEY(quote_id,version));
CREATE TABLE IF NOT EXISTS public.quote_commands(tenant_id uuid NOT NULL,idempotency_key text NOT NULL,quote_id uuid NOT NULL,result_json jsonb NULL,created_at timestamptz NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS public.quote_public_links(link_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_id uuid NOT NULL,quote_version integer NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz NULL,first_viewed_at timestamptz NULL,last_viewed_at timestamptz NULL,visit_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT NOW(),UNIQUE(quote_id,quote_version));
CREATE TABLE IF NOT EXISTS public.quote_decisions(decision_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_id uuid NOT NULL,quote_version integer NOT NULL,decision text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT NOW(),ip_hash text NOT NULL DEFAULT '',UNIQUE(quote_id,quote_version),CONSTRAINT ck_quote_decision CHECK(decision IN ('Accepted','Declined')));
""";
        await using var command=new NpgsqlCommand(sql,connection);await command.ExecuteNonQueryAsync(ct);
    }

    public static async Task<object> CatalogueAsync(NpgsqlConnection connection,Guid tenantId,CancellationToken ct=default)
    {
        var active=await TenantServiceCatalogueSupport.LoadActiveAsync(connection,tenantId,ct);
        var categories=active.Draft.Categories.ToDictionary(x=>x.Id,x=>x.Name);
        var services=active.Draft.Services.Where(x=>!x.Archived).Select(x=>{
            var binding=x.Bindings.FirstOrDefault(b=>b.Active&&b.InvoiceItemPrice.HasValue);
            return new{serviceId=x.Id,name=x.Name,categoryId=x.CategoryId,categoryName=categories.GetValueOrDefault(x.CategoryId,"Service"),description=binding?.InvoiceItemName??x.Name,unitPrice=binding?.InvoiceItemPrice,gstRate=0.15m,active=binding!=null};
        }).Where(x=>x.active).ToList();
        var modifiers=active.Draft.ModifierGroups.Where(x=>!x.Archived).SelectMany(g=>g.Options.Where(o=>o.Active&&o.InvoiceItemPrice.HasValue).Select(o=>new{modifierId=$"{g.Id:D}:{o.ListItemId}",groupId=g.Id,groupName=g.Name,name=o.ListItemName,description=o.InvoiceItemName,unitPrice=o.InvoiceItemPrice,gstRate=0.15m,active=true})).ToList();
        var quantityPricingRules=(active.Draft.QuantityPricingRules??[]).Where(x=>x.Active).Select(x=>new{ruleId=x.Id,source=x.SourceCanonicalField,invoiceItemId=x.InvoiceItemId,description=x.InvoiceItemName,unitRateInclGst=x.UnitRateInclGst,allCategories=x.AllCategories,categoryIds=x.CategoryIds,active=x.Active}).ToList();
        return new{catalogueVersion=active.Version,services,modifiers,quantityPricingRules};
    }

    public static async Task<object> ListAsync(NpgsqlConnection connection,Guid tenantId,CancellationToken ct=default)
    {
        await EnsureAsync(connection,ct);await EnsureSettingsAsync(connection,tenantId,ct);
        var quotes=new List<object>();const string sql="SELECT quote_id,quote_number,status,version,canonical_address,client_name,total,valid_until,updated_at FROM public.quotes WHERE tenant_id=@tenant ORDER BY updated_at DESC LIMIT 250";
        await using(var command=new NpgsqlCommand(sql,connection)){command.Parameters.AddWithValue("tenant",tenantId);await using var reader=await command.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))quotes.Add(new{quoteId=reader.GetGuid(0),quoteNumber=reader.GetString(1),status=EffectiveStatus(reader.GetString(2),reader.GetDateTime(7)),version=reader.GetInt32(3),canonicalAddress=reader.GetString(4),clientName=reader.GetString(5),total=reader.GetDecimal(6),validUntil=reader.GetDateTime(7).ToString("yyyy-MM-dd"),updatedAt=reader.GetDateTime(8)});}
        await using var setting=new NpgsqlCommand("SELECT default_validity_days FROM public.tenant_quote_settings WHERE tenant_id=@tenant",connection);setting.Parameters.AddWithValue("tenant",tenantId);var days=Convert.ToInt32(await setting.ExecuteScalarAsync(ct));return new{quotes,defaultValidityDays=days};
    }

    public static async Task<object?> LoadAsync(NpgsqlConnection connection,Guid tenantId,Guid quoteId,CancellationToken ct=default)
    {
        await EnsureAsync(connection,ct);const string sql="SELECT quote_id,quote_number,status,version,catalogue_version,canonical_address,place_id,latitude,longitude,client_name,client_email,property_json::text,imagery_json::text,suggestions_json::text,lines_json::text,subtotal,gst,total,valid_until,created_at,updated_at,accepted_at,declined_at FROM public.quotes WHERE tenant_id=@tenant AND quote_id=@quote";
        await using var command=new NpgsqlCommand(sql,connection);command.Parameters.AddWithValue("tenant",tenantId);command.Parameters.AddWithValue("quote",quoteId);await using var reader=await command.ExecuteReaderAsync(ct);if(!await reader.ReadAsync(ct))return null;return Row(reader,true);
    }

    public static async Task<QuoteSaveResult> SaveAsync(NpgsqlConnection connection,QuoteDraftSaveRequest request,string actor,string pepper,CancellationToken ct=default)
    {
        if(!request.Confirmed)throw new InvalidOperationException("Confirm the quote draft save.");if(string.IsNullOrWhiteSpace(request.IdempotencyKey))throw new InvalidOperationException("An idempotency key is required.");
